const webhookBody = $('Webhook').first()?.json?.body || {};
const apolloToken = (webhookBody.apollo_token || '').trim();
const calendlyToken = (webhookBody.calendly_token || '').trim();
const apolloConnected = apolloToken.length >= 8;
const calendlyConnected = calendlyToken.length >= 8;

const apollo = $('ApolloStats').first()?.json;
const apolloOk = apolloConnected && apollo && !apollo.error && !apollo.errors;
const emailsSent = apolloOk ? (apollo.num_sent ?? apollo.emails_sent ?? null) : null;
const numOpens = apolloOk ? (apollo.num_opens ?? apollo.opens ?? null) : null;
const numReplies = apolloOk ? (apollo.num_replies ?? apollo.replies ?? null) : null;

const events = $('CalendlyEvents').first()?.json;
const eventsOk = calendlyConnected && events && Array.isArray(events.collection);
const meetingsBooked = eventsOk ? events.collection.length : null;

const openRate = (emailsSent && emailsSent > 0 && numOpens != null) ? (numOpens / emailsSent) * 100 : null;
const replyRate = (emailsSent && emailsSent > 0 && numReplies != null) ? (numReplies / emailsSent) * 100 : null;
const meetingConversion = (emailsSent && emailsSent > 0 && meetingsBooked != null) ? (meetingsBooked / emailsSent) * 100 : null;

// Build 14-day reply sparkline from Apollo daily breakdowns if available, else null
let replySparkline = null;
if (apolloOk && Array.isArray(apollo.daily_replies)) {
  replySparkline = apollo.daily_replies.slice(-14);
} else if (apolloOk && Array.isArray(apollo.daily_stats)) {
  replySparkline = apollo.daily_stats.slice(-14).map(d => d.replies || 0);
}

return [{
  json: {
    emails_sent: emailsSent,
    open_rate_pct: openRate,
    reply_rate_pct: replyRate,
    reply_sparkline: replySparkline,
    meetings_booked: meetingsBooked,
    meeting_conversion_pct: meetingConversion,
    apollo_connected: apolloConnected,
    calendly_connected: calendlyConnected,
    period_label: 'Last 14 days'
  }
}];
